import matter from 'gray-matter';

export interface PageFrontmatter {
  title: string;
  date: string;
  tags: string[];
}

export interface PageData {
  slug: string;
  frontmatter: PageFrontmatter;
  content: string;
  html: string;
}

export interface ParseResult {
  pages: PageData[];
}

export interface ParseOptions {
  contentDir: string;
  outputDir: string;
}

import fs from 'fs';
import path from 'path';
import matter from 'gray-matter';
import { marked } from 'marked';
import { PageData, ParseResult, ParseOptions } from './types';

export function parseFiles({ contentDir }: ParseOptions): ParseResult {
  if (!fs.existsSync(contentDir)) {
    throw new Error(`Content directory not found: ${contentDir}`);
  }

  const files = fs.readdirSync(contentDir).filter((f) => f.endsWith('.md'));

  const pages: PageData[] = files.map((file) => {
    const filePath = path.join(contentDir, file);
    const raw = fs.readFileSync(filePath, 'utf-8');
    const { data, content } = matter(raw);

    const frontmatter = {
      title: String(data.title || file.replace(/\.md$/, '')),
      date: formatDate(data.date),
      tags: Array.isArray(data.tags) ? data.tags.map(String) : [],
    };

    const html = marked.parse(content.trim()) as string;
    const slug = file.replace(/\.md$/, '');

    return { slug, frontmatter, content, html };
  });

  return { pages };
}

function formatDate(date: unknown): string {
  if (date instanceof Date) {
    return date.toISOString().split('T')[0];
  }
  if (typeof date === 'string') {
    const match = date.match(/^\d{4}-\d{2}-\d{2}/);
    if (match) {
      return match[0];
    }
  }
  return '';
}

import fs from 'fs';
import path from 'path';
import { PageData, ParseResult } from './types';

function wrapPage(title: string, body: string): string {
  return `<!DOCTYPE html>
<html lang="en">
<head>
  <meta charset="UTF-8">
  <meta name="viewport" content="width=device-width, initial-scale=1.0">
  <title>${escapeHtml(title)}</title>
</head>
<body>
  ${body}
</body>
</html>`;
}

function escapeHtml(text: string): string {
  return text
    .replace(/&/g, '&amp;')
    .replace(/</g, '&lt;')
    .replace(/>/g, '&gt;')
    .replace(/"/g, '&quot;');
}

function renderIndex(pages: PageData[]): string {
  const sorted = [...pages].sort((a, b) =>
    b.frontmatter.date.localeCompare(a.frontmatter.date)
  );

  const items = sorted
    .map(
      (page) => `
    <article>
      <h2><a href="${escapeHtml(page.slug)}.html">${escapeHtml(page.frontmatter.title)}</a></h2>
      ${page.frontmatter.date ? `<time>${escapeHtml(page.frontmatter.date)}</time>` : ''}
      ${page.frontmatter.tags.length ? `<p>Tags: ${escapeHtml(page.frontmatter.tags.join(', '))}</p>` : ''}
    </article>`
    )
    .join('\n');

  const body = `
  <header>
    <h1>Blog</h1>
  </header>
  <main>
    ${items || '<p>No posts yet.</p>'}
  </main>`;

  return wrapPage('Blog', body);
}

function renderPage(page: PageData): string {
  const body = `
  <header>
    <h1>${escapeHtml(page.frontmatter.title)}</h1>
    ${page.frontmatter.date ? `<time>${escapeHtml(page.frontmatter.date)}</time>` : ''}
    ${page.frontmatter.tags.length ? `<p>Tags: ${escapeHtml(page.frontmatter.tags.join(', '))}</p>` : ''}
  </header>
  <main>
    ${page.html}
  </main>
  <footer>
    <a href="index.html">&larr; Back to index</a>
  </footer>`;

  return wrapPage(page.frontmatter.title, body);
}

export function generateSite(
  { pages }: ParseResult,
  outputDir: string
): void {
  if (!fs.existsSync(outputDir)) {
    fs.mkdirSync(outputDir, { recursive: true });
  }

  for (const page of pages) {
    const html = renderPage(page);
    fs.writeFileSync(path.join(outputDir, `${page.slug}.html`), html);
  }

  const indexHtml = renderIndex(pages);
  fs.writeFileSync(path.join(outputDir, 'index.html'), indexHtml);
}

#!/usr/bin/env node

import { parseFiles } from './parser';
import { generateSite } from './generator';

function parseArgs(args: string[]): { contentDir: string; outputDir: string; command: string } {
  const command = args[0] || 'build';
  let contentDir = './content';
  let outputDir = './dist';

  for (let i = 0; i < args.length; i++) {
    if (args[i] === '--content' && i + 1 < args.length) {
      contentDir = args[i + 1];
      i++;
    } else if (args[i] === '--output' && i + 1 < args.length) {
      outputDir = args[i + 1];
      i++;
    }
  }

  return { command, contentDir, outputDir };
}

function main() {
  const args = process.argv.slice(2);
  const { command, contentDir, outputDir } = parseArgs(args);

  if (command !== 'build') {
    console.error(`Unknown command: ${command}`);
    console.error('Usage: npx ssg build [--content <dir>] [--output <dir>]');
    process.exit(1);
  }

  try {
    const parseResult = parseFiles({ contentDir, outputDir });
    generateSite(parseResult, outputDir);
    console.log(`Site generated in ${outputDir}`);
  } catch (err: unknown) {
    const message = err instanceof Error ? err.message : String(err);
    console.error(`Error: ${message}`);
    process.exit(1);
  }
}

main();

